```python
def anti_shuffle(s):
    words = s.split(' ')
    sorted_words = [''.join(sorted(word)) for word in words]
    result = []

    for original, sorted_word in zip(words, sorted_words):
        if original == '':
            result.append('')
        else:
            result.append(sorted_word)

    return ' '.join(result)
